import{z as n,x as i,o as e,c as d,q as B,j as o,D as E,d as l,s as t,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"竞技场方法学","description":"","frontmatter":{"title":"竞技场方法学","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ef-arena-methodology.md","filePath":"llm/ef-arena-methodology.md","lastUpdated":1791413859000}'),m={name:"llm/ef-arena-methodology.md"};function p(C,a,h,D,f,u){const A=i("Mermaid");return e(),d("div",null,[a[2]||(a[2]=B('<h1 id="竞技场方法学" tabindex="-1">竞技场方法学 <a class="header-anchor" href="#竞技场方法学" aria-label="Permalink to &quot;竞技场方法学&quot;">​</a></h1><div class="epigraph"><p>竞技场不是「投完票算个 Elo」，而是一次对人类偏好分布的抽样调查：怎么配对、票怎么过滤、分数怎么估、区间多宽，每一步都在决定名次的资格。</p><footer>—— 据 Bradley 与 Terry 1952、Chiang 等 2024、Dubois 等 2024、Balduzzi 等 2018 整理</footer></div><p><a href="/llm/ef-llm-judge-deep">上一课</a>把法官标定成仪器，但法官仍是代理人，真票在人手里。<a href="/llm/lmsys-arena">Arena 课</a>写了滑动 Elo 的机制，<a href="/llm/arena-hard">Arena-Hard</a>写了怎么用法官代理它。本课深化竞技场本身的方法学：偏好票在什么模型下聚合、风格怎么控制、非平稳怎么处理、名次带多宽的区间。缺口是：同一堆票，用在线 Elo 还是批量似然、控不控长度，名次会不同——方法学就是把这些选择从默认变成声明。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一票是「匿名模型 A、B 各答一题，人选一个或平局」。把它变成名次需要三件事：一个胜率模型、一个估计量、一个抽样设计。朴素做法逐场更新 Elo，简单但对样本顺序与场次分配敏感；题目分布是「来什么答什么」，混进了不打算用于比较的流量；长度、标题、列表这些与能力无关的协变量在系统性加分。<span class="marginnote">「风格红利」就是与能力无关却能拉票的外观分：回答更长、标题更多、列表更整齐，看上去就更专业。多项研究证实长度与胜率强相关——投票者常把「写得像答案」误判成「答得对」，所以方法学的第一步是把这份红利先记账再扣除。</span>没有区间的一万名次变化，可能只是一周的投票波动，也可能只是风格红利。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>聚合</strong>：Bradley–Terry 模型把每场对战写成 \\(P(i\\ \\text{胜}\\ j)=\\sigma(\\beta_i-\\beta_j)\\)，对全部票做极大似然，一次估出强度 \\(\\beta_i\\)；在线 Elo 是它的一阶随机近似，适合滚动榜但保留顺序敏感性。<strong>区间</strong>：对题目与人做 bootstrap，每个名次报置信区间；<span class="marginnote">bootstrap 的直觉是「重抽平行宇宙」：把几十万张票有放回地重抽一千套，每套各算一遍名次，看名次落在哪一段。若某模型一千次里大多排在第 3 到第 7 之间，就报「第 3–7 名」；两个模型的区间不相交才敢说谁强，相交就只能承认这一手数据分不出胜负。</span>区间相交的名次差不下结论——这与<a href="/llm/aeval-crossmodel-pitfalls">跨模型比较的陷阱</a>的钉协议是同一条纪律。<strong>风格控制</strong>：把回答长度、标题数、列表数当协变量放进回归，估「控住风格后仍赢的概率」，Dubois 等的长度控制胜率是标准做法。<strong>抽样</strong>：主动配对让强度相近的模型多打，机器人与重复票先过滤，被猜破匿名的模型要标记并降权。</p>',7)),(e(),o(s,null,{default:E(()=>[t(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E5%8C%BF%E5%90%8D%E6%88%90%E5%AF%B9%E6%8A%95%E7%A5%A8%22%5D%20--%3E%20F%5B%22%E8%BF%87%E6%BB%A4%E6%9C%BA%E5%99%A8%E4%BA%BA%20%2F%20%E9%87%8D%E5%A4%8D%E7%A5%A8%22%5D%0A%20%20F%20--%3E%20BT%5B%22Bradley%E2%80%93Terry%20%E6%9E%81%E5%A4%A7%E4%BC%BC%E7%84%B6%22%5D%0A%20%20BT%20--%3E%20SC%5B%22%E9%A3%8E%E6%A0%BC%E5%8D%8F%E5%8F%98%E9%87%8F%E5%9B%9E%E5%BD%92%E6%8E%A7%E5%88%B6%22%5D%0A%20%20SC%20--%3E%20CI%5B%22bootstrap%20%E7%BD%AE%E4%BF%A1%E5%8C%BA%E9%97%B4%22%5D%0A%20%20CI%20--%3E%20R%5B%22%E5%90%8D%E6%AC%A1%E5%8A%A0%E5%8C%BA%E9%97%B4%E5%8F%91%E5%B8%83%22%5D%0A%20%20DR%5B%22%E6%8F%90%E7%A4%BA%E5%88%86%E5%B8%83%E6%BC%82%E7%A7%BB%E4%B8%8E%E6%96%B0%E6%A8%A1%E5%9E%8B%E8%BF%9B%E5%9C%BA%22%5D%20-.-%3E%20BT%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[l("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"BT 模型假设可传递性：A 常胜 B、B 常胜 C，就推出 A 常胜 C。真实偏好存在非传递循环——用户各有所爱、论域不同——单标量会把这个循环压扁，投影损失是真的；Balduzzi 等因此建议至少分域报强度，而不是一个总 Elo 吃下所有论域。风格控制的机制是扣除可观测协变量的贡献：控制后的胜率回答「若两边一样长，谁赢」；它修不了不可观测的风格（语气、族谱腔），所以仍要与人票对表。非平稳的机制是投票流本身在换：提示分布随产品与时间漂移，新模型进场改变对手池，于是要么给旧对战时间衰减，要么在版本冻结的窗口内重估——跨窗口的分数不可直接相减。",-1)),(e(),o(s,null,{default:E(()=>[t(A,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%A8%A1%E5%9E%8B%20A%22%5D%20--%3E%7C%22%E5%B8%B8%E8%83%9C%22%7C%20B%5B%22%E6%A8%A1%E5%9E%8B%20B%22%5D%0A%20%20B%20--%3E%7C%22%E5%B8%B8%E8%83%9C%22%7C%20C%5B%22%E6%A8%A1%E5%9E%8B%20C%22%5D%0A%20%20C%20--%3E%7C%22%E5%8F%88%E5%B8%B8%E8%83%9C%20A%22%7C%20LOOP%5B%22%E9%9D%9E%E4%BC%A0%E9%80%92%E5%BE%AA%E7%8E%AF%3A%20%E5%8D%95%E4%B8%AA%E6%A0%87%E9%87%8F%E8%A3%85%E4%B8%8D%E4%B8%8B%22%5D%0A%20%20LOOP%20--%3E%20SQ%5B%22%E5%BC%BA%E8%A1%8C%E5%8E%8B%E6%88%90%E4%B8%80%E6%9D%A1%E6%80%BB%E6%A6%9C%3Cbr%2F%3E%E6%80%BB%E6%9C%89%E4%B8%80%E5%AF%B9%E8%A2%AB%E6%8E%92%E5%8F%8D%22%5D%0A%20%20LOOP%20-.-%3E%7C%E5%87%BA%E8%B7%AF%7C%20DOM%5B%22%E5%88%86%E5%9F%9F%E6%8A%A5%E5%BC%BA%E5%BA%A6%3Cbr%2F%3E%E6%AF%8F%E4%B8%AA%E8%AE%BA%E5%9F%9F%E4%B8%80%E4%B8%AA%E6%A0%87%E9%87%8F%20%E5%BE%AA%E7%8E%AF%E5%A4%A7%E5%A4%9A%E6%B6%88%E5%A4%B1%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">主动配对的道理同测验选题：两个强度差很远的模型对战，胜率接近 0 或 1，一场几乎不改变估计；把预算花在 \\(\\beta_i\\approx\\beta_j\\) 的配对上，同样票数下区间更窄。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>竞技场测的是「这批投票者在这些提示上的偏好」，不是能力：数学对错投票者未必判得了，<a href="/llm/human-vs-auto-eval">可程序判定的任务</a>不要进 Arena。提示分布与你的产品分布不同时，名次对外部场景没有效度——「与 Arena 相关」是协议、题集、法官三者的联合性质。匿名性是脆的：新模型常被从腔调猜出，票里混进粉丝效应，发布方至少要做去匿名哨兵检查。开放榜还会被策略性投票与提示瞄准，公开名次永远带这条警戒线。<span class="marginnote">初学者容易把 Arena 榜当「能力榜」，它其实是「偏好榜」：投票者凭观感投票，数学算得对不对未必看得出来。拿它回答「哪个模型写代码 bug 更少」，就像让观众给体操打技术难度分——好看不等于动作正确，技术活要交给能验算的评测。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>票到名次的三件事：胜率模型、估计量、抽样设计；每件都要声明而不是默认。</li><li>批量 BT 加区间是主尺，在线 Elo 只作滚动参考；区间相交不下名次结论。</li><li>风格控制扣除可观测协变量，修不了不可观测的偏好，人票对表不可省。</li><li>非传递与非平稳是单标量的两处投影损失；跨窗口分数不可直接减。</li><li>出处：Bradley 与 Terry 1952；Elo 1978；Chiang 等 2024（Chatbot Arena）；Dubois 等 2024（长度控制 AlpacaEval）；Balduzzi 等 2018。</li></ul>',5))])}const F=n(m,[["render",p]]);export{b as __pageData,F as default};
